        "t_299": "⚡ OTROS (Especificación personalizada)",
        "t_300": "// CUÉNTANOS TU PROYECTO: OBJETIVOS Y PLAZOS",
        "t_301": "Ideas, presupuesto orientativo y fechas",
        "t_302": "SOLICITAR PRESUPUESTO →",
