        "t_326": "<span class=\"font-headline text-3xl tracking-tight text-signal-red group-hover:scale-105 transition-transform\">CHUS BZN</span> <span class=\"hidden sm:inline-block font-mono text-[10px] text-white/50 tracking-widest uppercase border-l border-white/20 pl-3\">ESTUDI AUDIOVISUAL I TECNOLÒGIC</span>",
        "t_328": "CHUS BZN // <br/> <span class=\"text-signal-red\">CINEMA · TELEVISIÓ · SO · IA</span>",
        "t_329": "<strong>CHUS BZN</strong> és una productora audiovisual i tecnològica a Barcelona. Cinema, televisió, so i integració d'IA aplicats a la comunicació de pimes i marques.",
        "t_353": "// NIVELL 3 (GRAU SUPERIOR) — SO PER A AUDIOVISUALS",
        "t_354": "// NIVELLS 2 I 1 — ANIMACIÓ MUSICAL, VISUAL I IMATGE",
        "t_boot_1": "> ESTUDI AUDIOVISUAL I TECNOLÒGIC · BARCELONA",
