        "t_hero_sub": "Strategic fusion between analog sound engineering and the cutting edge of Generative AI. Three decades leading critical infrastructures in film, TV and urban environments.",
        "t_meth_p1": "CHUS BZN is a pioneering audiovisual agency and collective in Barcelona in the creation and development of custom audiovisual and technological projects.",
        "t_meth_p2": "We specialize in the creation, integration, development, automation and implementation of Artificial Intelligence in businesses or companies, operating under strict compliance with European regulations (EU AI Act).",
        "t_meth_title": "Hybrid Methodology & Senior Collective",
        "t_service_design_code": "// DOSSIER 06 - MOTION GRAPHICS & GRAPHIC DESIGN",
        "t_service_design_desc": "Creation of 2D/3D animated visual elements, bumpers for television channels, graphic continuity packages for live broadcasts and brand design.",
        "t_service_design_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Advanced animations in After Effects and Blender.<br/>• High resolution photographic and graphic composition.<br/>• <strong>Client application:</strong> High-impact corporate image, promotions and graphics for events.",
        "t_service_design_title": "Motion Graphics & Visual Identity",
        "t_service_dj_code": "// DOSSIER 13 – DJ SESSIONS & PERFORMANCES",
        "t_service_dj_desc": "Musical atmosphere for your event with DJ sets and signature performances, with the energy your audience remembers.",
        "t_service_dj_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Operation with high-end Pioneer professional hardware (DDJ1000 / Rekordbox).<br/>• Room acoustic study and exclusive studio remixes adapted to the profile of the event.<br/>• <strong>Client application:</strong> Large format events, brand conventions and record production.",
        "t_service_dj_title": "DJ sessions & performances",
        "t_service_formacion_code": "// DOSSIER 07 – VIDEO TRAINING",
        "t_service_formacion_desc": "Courses, tutorials and onboarding videos so your team learns and grows, in a clear format that is easy to watch and understand.",
        "t_service_formacion_specs": "<strong>Solution & Deliverables:</strong><br/>• On-demand training pieces: onboarding, product tutorials and internal training.<br/>• Production supported by AI and adapted to your team's level.<br/>• <strong>Application:</strong> train without stopping operations and review the content whenever you need.",
        "t_service_formacion_title": "Video training",
        "t_service_ia_code": "// DOSSIER 08 – AI FOR YOUR COMMUNICATION",
        "t_service_ia_desc": "We implement AI in your company to produce more content in less time: catalogue, ads, avatars and workflows, with legal protection.",
        "t_service_ia_specs": "<strong>Solution & Deliverables:</strong><br/>• Licensed voice rights: legal security included.<br/>• From a single original source we produce catalogue, ads and derived pieces.<br/>• <strong>Application:</strong> lower cost and content in seconds, without losing your brand image.",
        "t_service_ia_title": "AI for your communication",
        "t_service_sonido_code": "// DOSSIER 05 – SOUND & MUSIC FOR YOUR BRAND",
        "t_service_sonido_desc": "Sound identity, jingles, voice-over and mixes with the quality of major productions. Also live music for your events and venues.",
        "t_service_sonido_specs": "<strong>Solution & Deliverables:</strong><br/>• Mixing and mastering with consistent levels: your content sounds great on every platform.<br/>• The «sound of your brand»: consistent jingles, themes and voice-overs across everything you publish.<br/>• <strong>Application:</strong> sound identity, ambient music, DJ sets and remixes for large-format events.",
        "t_service_sonido_title": "Sound & music for your brand",
        "t_service_streaming_code": "// DOSSIER 03 – LIVE & STREAMING",
        "t_service_streaming_desc": "We cover your events, launches, open days and congresses live with broadcast quality and simultaneous streaming to your channels.",
        "t_service_streaming_specs": "<strong>Solution & Deliverables:</strong><br/>• Multi-camera, professional audio and real-time colour control.<br/>• Simultaneous streaming to several platforms without interruptions.<br/>• <strong>Application:</strong> your event watched by your audience in real time, with broadcast reliability.",
        "t_service_streaming_title": "Live & streaming",
        "t_service_video_code": "// DOSSIER 01 – CORPORATE VIDEO",
        "t_service_video_desc": "We present your company, product or team in a clear, professional video, with the image and sound quality of major productions.",
        "t_service_video_specs": "<strong>Solution & Deliverables:</strong><br/>• Multicamera shoot in studio or at your premises, in 4K/8K with cinema colour.<br/>• Script and direction focused on the client: a message understood in one minute.<br/>• <strong>Application:</strong> a demo that looks and sounds professional on your site, channels and sales meetings.",
        "t_service_video_title": "Corporate video",
        "t_service_web_code": "// DOSSIER 10 – WEBSITES & CAMPAIGNS",
        "t_service_web_desc": "Your website and your videos working together: a clear, fast landing page designed to turn visits into clients.",
        "t_service_web_specs": "<strong>Solution & Deliverables:</strong><br/>• Landing pages that load in under a second, built for video and mobile.<br/>• Your pieces integrated into the page that sells for you.<br/>• <strong>Application:</strong> from visit to form in a single click.",
        "t_service_web_title": "Websites & campaigns",
