        "t_318": "→ Профессиональный профиль",
        "t_326": "<span class=\"font-headline text-3xl tracking-tight text-signal-red group-hover:scale-105 transition-transform\">CHUS BZN</span> <span class=\"hidden sm:inline-block font-mono text-[10px] text-white/50 tracking-widest uppercase border-l border-white/20 pl-3\">АУДИОВИЗУАЛЬНАЯ И ТЕХНОЛОГИЧЕСКАЯ СТУДИЯ</span>",
