        "t_128": "<img alt=\"CHUS BZN Logo Oficial\" class=\"h-11 sm:h-12 w-auto object-contain border border-white/20 p-0.5 rounded group-hover:border-signal-red transition-all group-hover:scale-105\" src=\"assets/logo.jpg\"/><span class=\"hidden sm:inline-block font-mono text-[10px] text-white/50 tracking-widest uppercase border-l border-white/20 pl-3\">АУДИОВИЗУАЛЬНЫЕ УСЛУГИ И ЦЕНТР ИИ</span>",
