        "t_124": "[محطة مفتوحة] // حقوق الطبع والنشر لعام 2026 لـ JESÚS FERRER GARCÍA // جميع الأنظمة قيد التشغيل",
        "t_125": "06. المدونة",
        "t_126": "المدونة والأخبار",
        "t_127": "مساحة مخصصة لمشاركة التطورات التقنية والاختبارات المعملية مع الذكاء الاصطناعي وتكامل الأنظمة السمعية والبصرية والتأملات في النظام البيئي الرقمي المعاصر.",
        "t_128": "<img alt=\"CHUS BZN Logo Oficial\" class=\"h-11 sm:h-12 w-auto object-contain border border-white/20 p-0.5 rounded group-hover:border-signal-red transition-all group-hover:scale-105\" src=\"assets/logo.jpg\"/><span class=\"hidden sm:inline-block font-mono text-[10px] text-white/50 tracking-widest uppercase border-l border-white/20 pl-3\">الخدمات السمعية والبصرية ومركز الذكاء الاصطناعي</span>",
        "t_129": "02. أين ترى الوظائف",
        "t_130": "04. مقاطع فيديو حية",
        "t_131": "05. السيرة الذاتية",
        "t_132": "06. المدونة",
        "t_133": "🇪🇸 إن",
        "t_134": "🇬🇧 في",
        "t_135": "🇩🇪 دي",
        "t_136": "🇷🇺 رو",
        "t_137": "🇯🇵 ها",
        "t_138": "🇺🇦 المملكة المتحدة",
        "t_139": "🇨🇳 ز.ه",
